package service_test

import (
	"legacy_refactor/rep-1/internal/service"
	"testing"
)

func TestUserService_CreateUser(t *testing.T) {
	svc := service.NewUserService()

	user := service.User{Name: "John Doe", Email: "john@example.com"}
	createdUser, err := svc.CreateUser(user)
	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}

	if createdUser.ID == "" {
		t.Error("expected user ID to be generated, got empty")
	}
	if createdUser.Name != user.Name {
		t.Errorf("expected name %s, got %s", user.Name, createdUser.Name)
	}

	retrievedUser, err := svc.GetUserByID(createdUser.ID)
	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	if retrievedUser.ID != createdUser.ID {
		t.Errorf("expected user ID %s, got %s", createdUser.ID, retrievedUser.ID)
	}
}

func TestUserService_GetUserByID(t *testing.T) {
	svc := service.NewUserService()

	_, err := svc.GetUserByID("nonexistent-id")
	if err == nil {
		t.Error("expected error for non-existent user, got nil")
	}

	user := service.User{Name: "Jane Doe", Email: "jane@example.com"}
	createdUser, _ := svc.CreateUser(user)

	retrievedUser, err := svc.GetUserByID(createdUser.ID)
	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	if retrievedUser.Name != user.Name {
		t.Errorf("expected user name %s, got %s", user.Name, retrievedUser.Name)
	}
}

func TestUserService_GetAllUsers(t *testing.T) {
	svc := service.NewUserService()

	users := svc.GetAllUsers()
	if len(users) != 0 {
		t.Errorf("expected 0 users, got %d", len(users))
	}

	user1 := service.User{Name: "Alice", Email: "alice@example.com"}
	user2 := service.User{Name: "Bob", Email: "bob@example.com"}

	svc.CreateUser(user1)
	svc.CreateUser(user2)

	allUsers := svc.GetAllUsers()
	if len(allUsers) != 2 {
		t.Errorf("expected 2 users, got %d", len(allUsers))
	}
}

package api_test

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"legacy_refactor/rep-1/internal/api"
	"legacy_refactor/rep-1/internal/service"
)

func TestUserHandlers(t *testing.T) {
	userService := service.NewUserService()
	handler := api.NewUserHandler(userService)

	t.Run("CreateUser", func(t *testing.T) {
		user := service.User{Name: "Test User", Email: "test@example.com"}
		body, _ := json.Marshal(user)
		req := httptest.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(body))
		req.Header.Set("Content-Type", "application/json")
		rr := httptest.NewRecorder()

		handler.HandleUsers(rr, req)

		if status := rr.Code; status != http.StatusCreated {
			t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusCreated)
		}

		var createdUser service.User
		json.NewDecoder(rr.Body).Decode(&createdUser)
		if createdUser.ID == "" {
			t.Error("expected user ID to be generated, got empty")
		}
		if createdUser.Name != user.Name {
			t.Errorf("expected user name %s, got %s", user.Name, createdUser.Name)
		}
	})

	// Get all users
	t.Run("GetAllUsers", func(t *testing.T) {
		req := httptest.NewRequest(http.MethodGet, "/users", nil)
		rr := httptest.NewRecorder()

		handler.HandleUsers(rr, req)

		if status := rr.Code; status != http.StatusOK {
			t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
		}

		var users []service.User
		json.NewDecoder(rr.Body).Decode(&users)
		if len(users) != 1 {
			t.Errorf("expected 1 user, got %d", len(users))
		}
		if users[0].Name != "Test User" {
			t.Errorf("expected user name 'Test User', got %s", users[0].Name)
		}

		// Store the ID for the next test
		t.Setenv("TEST_USER_ID", users[0].ID)
	})

	// Get user by ID
	t.Run("GetUserByID", func(t *testing.T) {
		userID := t.Getenv("TEST_USER_ID")
		if userID == "" {
			t.Fatal("TEST_USER_ID not set, cannot run GetUserByID test")
		}

		req := httptest.NewRequest(http.MethodGet, "/users/"+userID, nil)
		rr := httptest.NewRecorder()

		handler.HandleUserByID(rr, req)

		if status := rr.Code; status != http.StatusOK {
			t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
		}

		var retrievedUser service.User
		json.NewDecoder(rr.Body).Decode(&retrievedUser)
		if retrievedUser.ID != userID {
			t.Errorf("expected user ID %s, got %s", userID, retrievedUser.ID)
		}
		if retrievedUser.Name != "Test User" {
			t.Errorf("expected user name 'Test User', got %s", retrievedUser.Name)
		}
	})
}

